F-install-without-build.filterlib:
exit=0
module INV (A, Y);
  input A;
  output Y;
  assign Y = (~A); // "A'"
endmodule
module NAND2 (A, B, Y);
  input A;
  input B;
  output Y;
  assign Y = (~(A&B)); // "(A B)'"
endmodule
module DFF (C, D, Q);
  reg IQ, IQN;
  input C;
  input D;
  output Q;
  assign Q = IQ; // "IQ"
  always @(posedge C) begin
      IQ <= D;
  end
  always @(posedge C) begin
      IQN <= ~(D);
  end
endmodule

